mapper.select:
SELECT A.REQUEST_KEY , A.REQ_BUY_TYPE_CD , A.OPER_TYPE_CD , LPAD(A.RES_NO, 14, '0') as MVNO_ORD_NO -- MVNO 오더번호 , A.CUST_ID AS CUST_NO -- 고객아이디 , A.CONTRACT_NUM AS SVC_CONT_ID --서비스계약번호 , A.OPEN_NO as TLPH_NO -- 전화번호 :: 기기변경 인증한 번호를 OPEN_NO 에 저장하기로 함. , (CASE WHEN (C.ENGG_MNTH_CNT > '0') THEN 'H01' ELSE 'H11' END) as ODER_TYPE_CD -- 오더유형코드 , (CASE WHEN (C.ENGG_MNTH_CNT > '0') THEN 'Y' ELSE 'N' END) as INST_YN -- 할부여부 (우수기변일 경우에만 필수, 그외에 Y 라면 오류) , 'Y' as INDV_INFO_INER_PRCUSE_AGRE_YN -- 개인정보내부활용동의여부 , 'Y' as CRDT_INFO_AGRE_YN -- 신용정보동의여부 , 'N' as SPAM_PRVD_AGRE_YN -- 스팸제공동의여부 , (CASE WHEN (A.CSTMR_TYPE_CD = 'JP' or A.CSTMR_TYPE_CD = 'GO') THEN '02' WHEN (A.CSTMR_TYPE_CD = 'FN' or A.CSTMR_TYPE_CD = 'FM') THEN '05' ELSE '01' END) as CUST_IDNT_NO_IND_CD -- 고객식별번호구분코드 : 신분증유형코드로 매칭 (RCP2006 참고) , (CASE WHEN A.CSTMR_TYPE_CD = 'NA' THEN B.CSTMR_NATIVE_RRN WHEN A.CSTMR_TYPE_CD = 'NM' THEN B.CSTMR_NATIVE_RRN WHEN A.CSTMR_TYPE_CD = 'FN' THEN B.CSTMR_FOREIGNER_RRN WHEN A.CSTMR_TYPE_CD = 'FM' THEN B.CSTMR_FOREIGNER_RRN ELSE B.CSTMR_JURIDICAL_BIZ_NO END) as CUST_IDNT_NO -- 고객식별번호 , (CASE WHEN (A.CSTMR_TYPE_CD = 'JP' OR A.CSTMR_TYPE_CD = 'GO') THEN B.CSTMR_JURIDICAL_RRN ELSE '' END) as CRPR_NO -- 법인번호 (공공기관도 추가함) , B.CSTMR_NM as CUST_NM -- 고객명 , (CASE WHEN (A.CSTMR_TYPE_CD = 'JP' or A.CSTMR_TYPE_CD = 'GO') THEN B.CSTMR_JURIDICAL_BIZ_NO_ISSU_DATE ELSE A.IDENTITY_ISSU_DATE END) as RSDCRT_ISSU_DATE -- 신분증발급일자 (법인,공공은 사업자교부일자, 그외는 신분증발급일자) , (CASE WHEN A.CSTMR_TYPE_CD IN ('NA', 'FN') THEN CASE A.IDENTITY_TYPE_CD WHEN '01' THEN 'REGID' WHEN '02' THEN 'DRIVE' WHEN '03' THEN 'HANDI' WHEN '04' THEN 'MERIT' WHEN '05' THEN 'PPORT' WHEN '06' THEN 'FORGN' END WHEN A.CSTMR_TYPE_CD IN ('NM','FM') THEN 'COURT' WHEN (A.CSTMR_TYPE_CD IN ('JP','GO') AND COALESCE(B.CSTMR_VISIT_TYPE_CD,'')='VDP') THEN 'COURT' ELSE '' END) as NATIVE_RLNAM_ATHN_EVDN_PPR_CD -- 고객식별번호구분코드 : 신분증유형코드로 매칭 (RCP2006 참고) - 법인과 공공기관은 제외처리 (2026.06.30) / 미성년자는 COURT 로 고정 (2026.07.10) / 공공기관 및 법인에 COURT (2026.07.21) , (CASE WHEN A.IDENTITY_TYPE_CD = '02' THEN A.DRIVE_LICNS_NO ELSE '' END) as LCNS_NO -- 면허번호 , (CASE WHEN A.IDENTITY_TYPE_CD = '02' THEN A.IDENTITY_ISSU_REGION ELSE '' END) as LCNS_RGN_CD -- 면허지역코드 , (CASE WHEN A.IDENTITY_TYPE_CD = '04' THEN A.DRIVE_LICNS_NO ELSE '' END) as MRTR_PRSN_NO -- 유공자번호 :: (CASE WHEN A.IDENTITY_TYPE_CD = '04' THEN A.SELF_ISSU_NUM ELSE '' END) , (CASE WHEN (A.CSTMR_TYPE_CD = 'FN' OR A.CSTMR_TYPE_CD = 'FM') THEN B.CSTMR_FOREIGNER_NATION ELSE '' END) as NATIONALITY_CD -- 국적코드 , (CASE WHEN (A.CSTMR_TYPE_CD = 'FN' OR A.CSTMR_TYPE_CD = 'FM') THEN B.CSTMR_FOREIGNER_BIRTH ELSE '' END) as FORN_BRTH_DATE -- 외국인생일일자
, CASE WHEN (LENGTH(A.FATH_TEL_NO) > 9) THEN FATH_TEL_NO WHEN (LENGTH(A.FATH_MOBILE_FN_NO||A.FATH_MOBILE_MN_NO||A.FATH_MOBILE_RN_NO) > 9) THEN (A.FATH_MOBILE_FN_NO||A.FATH_MOBILE_MN_NO||A.FATH_MOBILE_RN_NO) ELSE (B.CSTMR_MOBILE_FN_NO || B.CSTMR_MOBILE_MN_NO || B.CSTMR_MOBILE_RN_NO) END as ATHN_RQSTCUST_CNTPLC_NO -- 인증요청고객연락처번호 , 'Y' as MYSL_AGRE_YN -- 서식아이디 있는 경우 본인인증 N 값이 맞음. N 값은 안된데... Y 로 해야하네. , (CASE WHEN (A.CSTMR_TYPE_CD = 'JP' or A.CSTMR_TYPE_CD = 'GO') THEN CASE WHEN (CSTMR_VISIT_TYPE_CD = 'VDP') THEN '04' ELSE '04' END ELSE '' END) AS AGNT_RLTN_CD -- 대리인관계코드 (법인 및 공공기관의 본인/대표일 경우 04 고정 처리 (01 허용되지 않음) - 2026.07.08)
, (CASE WHEN (A.CSTMR_TYPE_CD = 'JP' or A.CSTMR_TYPE_CD = 'GO') THEN CASE WHEN CSTMR_VISIT_TYPE_CD = 'VDP' THEN D.JRDCL_AGENT_RRN ELSE '20000101' END END) AS JRDCL_AGENT_RRN -- 대리인 생년월일 (YYMMDD) - 법인 및 공공기관의 대리인생년월일은 java 에서 복호화하여 처리필요 - 2026.07.24 , C.MODEL_ID AS INTM_MODEL_ID -- 기기모델아이디 , A.REQ_PHONE_SN as INTM_SRL_NO -- 기기일련번호 , C.SOC_CODE AS PRDC_CD -- 상품코드 , 'P' AS PRDC_TYPE_CD -- 상품타입코드 : 고정 (부가서비스는 프론트에서 제외함) , (CASE WHEN (A.USIM_KINDS_CD='02' OR A.USIM_KINDS_CD='07' OR A.USIM_KINDS_CD='08') THEN A.REQ_USIM_SN ELSE '' END) as ICC_ID -- USIM 일련번호 , '' AS SPCL_SLS_NO -- 판매정책번호 :: 호출 전에 조회해서 추가해줌. , 'KM1' AS SPNSR_TERM_TYPE_CD --스폰서약정 유형코드 :: 오더유형코드가 'H01'인 경우 필수 KM1 : 알뜰폰스폰서 , MC1 : 스마트스폰서(알뜰폰) , MC2 : 스마트할인(알뜰폰) , (CASE WHEN (COALESCE(C.ENGG_MNTH_CNT, 0) = '0') THEN '0' ELSE C.ENGG_MNTH_CNT END) AS ENGG_MNTH_CNT -- 약정개월수 , C.SPRT_TYPE_CD AS SALE_ENGT_OPTN_CD -- 할인유형코드 , (CASE WHEN A.USIM_KINDS_CD='09' THEN 'Y' ELSE '' END) as ESIM_USE_YN -- eSIM 사용여부 , (CASE WHEN A.USIM_KINDS_CD='09' THEN A.EID ELSE '' END) as EUICC_ID -- EID , A.CPNT_ID as CNTPNT_CD -- 접점코드 , (CASE WHEN (COALESCE(A.KNOTE_SCAN_ID,'') != '') THEN A.KNOTE_SCAN_ID ELSE A.FATH_TRANSAC_ID END) as FRMPAP_ID -- 2026.07.16 (knote서식지아이디 또는 트랜잭션 아이디) , (CASE WHEN (COALESCE(A.KNOTE_SCAN_ID,'') = '' AND COALESCE(A.FATH_TRANSAC_ID,'') != '') THEN 'Y' END) as ISELF_FRMPAP_YN -- 자체 서식지 여부 2026.07.15 , 'N' as MYSLF_ATHN_YN -- 본인인증여부 , '' as IPIN_CI -- 본인인증(CI) , '71' as ONLINE_ATHN_DIV_CD -- 본인인증 수단 >> (SELECT ETC5 FROM CMN_GRP_CD_MST@DL_MSP WHERE GRP_ID = 'RCP2001' AND CD_VAL = A.ONLINE_AUTH_TYPE) AS onlineAthnDivCd /* 본인인증 수단 */ -- 삭제컬럼(ONLINE_AUTH_TYPE) , '' as PHOTO_ATHN_TXN_SEQ -- 사진인증내역일련번호 , A.FATH_TRANSAC_ID as FATH_TRANSAC_ID -- 안면인증 트랜잭션 아이디 , A.CPNT_ID as CPNT_ID -- 접점코드 , A.AGENT_CD -- 대리점코드 FROM MSF_REQUEST_TEMP A LEFT JOIN MSF_REQUEST_CSTMR_TEMP B ON A.REQUEST_KEY = B.REQUEST_KEY LEFT JOIN MSF_REQUEST_SALE_TEMP C ON A.REQUEST_KEY = C.REQUEST_KEY LEFT OUTER JOIN MSF_REQUEST_AGENT_TEMP D ON B.REQUEST_KEY = D.REQUEST_KEY LEFT OUTER JOIN MSF_REQUEST_MOVE_TEMP E ON A.REQUEST_KEY = E.REQUEST_KEY WHERE A.REQUEST_KEY = #{requestKey}
